// Package mslgen makes the Metal back-end's raster kernel from kernel.wgsl,
// through go-gfx/wgsl's MSL emitter, so the raster arithmetic (coverage, tile
// walk and integer blend) is written once in WGSL instead of once per shading
// language.
package mslgen

import (
	"fmt"

	"github.com/go-gfx/wgsl"
	"github.com/go-gfx/wgsl/msl"
)

// Header opens the generated file.
const Header = "// Code generated by internal/mslgen from kernel.wgsl; DO NOT EDIT.\n\n"

// Kernel is the MSL for the WGSL compute kernel "raster": the preamble, the
// structures, the functions it calls and the kernel itself, its buffers at
// [[buffer(binding)]].
func Kernel(kernel string) (string, error) {
	m, err := wgsl.Parse(kernel)
	if err != nil {
		return "", err
	}
	info, errs := wgsl.Check(m)
	if len(errs) > 0 {
		return "", fmt.Errorf("mslgen: the kernel does not check: %v", errs)
	}
	out, err := msl.Module(m, info, "raster")
	if err != nil {
		return "", err
	}
	return Header + out, nil
}
